import type { Point, Box, ResolvedEndpoint, RoutedWire } from '../../contract/records/geometry.js';
import type { VisualWire } from '../../contract/records/input.js';
import type { SupplementalMeasurements } from '../../contract/types.js';
import { samePoint, overlaps } from '../geometry/intersections.js';
import { approach } from './endpoints.js';
import { clear, segments } from './paths.js';
import { reject } from '../validation/outcomes.js';
/** Determine whether the first/last segment extends outward along the resolved named side. */
function outward(
  endpoint: ResolvedEndpoint,
  adjacent: Point | undefined,
  advance: number,
): boolean {
  if (adjacent === undefined) return false;
  const expected = approach(endpoint, Math.max(advance, 0.000001));
  return inDirection(endpoint.point, expected, adjacent);
}
/** The adjacent point must be beyond the marker's reserved length on the exact departure ray. */
function inDirection(origin: Point, expected: Point, actual: Point): boolean {
  if (origin.x === expected.x)
    return followsRay(origin.y, expected.y, actual.y, actual.x - origin.x);
  return followsRay(origin.x, expected.x, actual.x, actual.y - origin.y);
}
/** Ray distance is signed; the perpendicular coordinate must remain on the attachment axis. */
function followsRay(
  origin: number,
  expected: number,
  actual: number,
  perpendicular: number,
): boolean {
  return (
    Math.abs(perpendicular) < 0.000001 &&
    (actual - origin) * (expected - origin) >= (expected - origin) ** 2 - 0.000001
  );
}
/** Marker bounds use supplied Presentation metrics, oriented along the endpoint ray. Layout execute catches structured faults; Authoring retains the scene and owns correction. */
export function markerBox(
  endpoint: ResolvedEndpoint,
  metric: { readonly advance: number; readonly halfHeight: number },
): Box {
  const end = approach(endpoint, metric.advance);
  const horizontal = endpoint.side === 'left' || endpoint.side === 'right';
  if (horizontal)
    return {
      x: Math.min(endpoint.point.x, end.x),
      y: endpoint.point.y - metric.halfHeight,
      width: Math.max(0.000001, metric.advance),
      height: Math.max(0.000001, metric.halfHeight * 2),
    };
  return {
    x: endpoint.point.x - metric.halfHeight,
    y: Math.min(endpoint.point.y, end.y),
    width: Math.max(0.000001, metric.halfHeight * 2),
    height: Math.max(0.000001, metric.advance),
  };
}
/** Route checking is reused after native routing and by independent candidate inspection. Layout execute catches structured faults; Authoring retains the scene and owns correction. */
export function validRoute(
  points: readonly Point[],
  source: ResolvedEndpoint,
  target: ResolvedEndpoint,
  obstacles: readonly Box[],
  wire: VisualWire,
  metrics: SupplementalMeasurements,
): boolean {
  return (
    endpointsMatch(points, source, target) &&
    clear(points, obstacles) &&
    markersClear(source, target, wire, metrics, obstacles) &&
    outward(source, points[1], metrics.markers[wire.sourceMarker].advance) &&
    outward(target, points.at(-2), metrics.markers[wire.targetMarker].advance)
  );
}
/** The path begins and ends at the resolved ports, including exact measured member row heights. */
function endpointsMatch(
  points: readonly Point[],
  source: ResolvedEndpoint,
  target: ResolvedEndpoint,
): boolean {
  const first = points[0];
  const last = points.at(-1);
  if (first === undefined || last === undefined) return false;
  return samePoint(first, source.point) && samePoint(last, target.point);
}
/** Labels reserve measured dimensions and avoid both content and previously accepted label/marker regions. Layout execute catches structured faults; Authoring retains the scene and owns correction. */
export function checkLabel(box: Box, wire: VisualWire, occupied: readonly Box[]): void {
  if (box.width !== wire.label.width || box.height !== wire.label.height)
    reject('invalid-input', wire.id, 'Wire label dimensions differ from measured content');
  if (occupied.some((other) => overlaps(box, other)))
    reject('constraint-conflict', wire.id, 'Wire label overlaps reserved content');
}
/** Crossings are warnings rather than silently classified as a semantic invalidity. Layout execute catches structured faults; Authoring retains the scene and owns correction. */
export function crosses(a: RoutedWire, b: RoutedWire): boolean {
  return segments(a.points).some((left) =>
    segments(b.points).some((right) => crossing(left.a, left.b, right.a, right.b)),
  );
}
/** Strict interior intersection excludes shared endpoints and collinear overlap. */
function crossing(a: Point, b: Point, c: Point, d: Point): boolean {
  if (a.y === b.y) return horizontalCrossing(a, b, c, d);
  return horizontalCrossing(c, d, a, b);
}
/** Check a horizontal/vertical pair using strict interior intervals; same-axis lines do not count. */
function horizontalCrossing(a: Point, b: Point, c: Point, d: Point): boolean {
  return a.y === b.y && c.x === d.x && inside(c.x, a.x, b.x) && inside(a.y, c.y, d.y);
}
/** Open intervals exclude shared ports and bends from crossing warnings. */
function inside(value: number, a: number, b: number): boolean {
  return value > Math.min(a, b) && value < Math.max(a, b);
}

/** Full measured marker rectangles must clear content; Layout's protected boundary owns correction after rejection. */
function markersClear(
  source: ResolvedEndpoint,
  target: ResolvedEndpoint,
  wire: VisualWire,
  metrics: SupplementalMeasurements,
  obstacles: readonly Box[],
): boolean {
  const boxes = [
    markerBox(source, metrics.markers[wire.sourceMarker]),
    markerBox(target, metrics.markers[wire.targetMarker]),
  ];
  return boxes.every((box): boolean =>
    obstacles.every((obstacle): boolean => !overlaps(box, obstacle)),
  );
}

import type { Box, Point } from '../../contract/records/geometry.js';
import type { Connection } from '../../contract/records/problem.js';
import type { RoutePlan } from './native.js';
import { union, pointBounds } from '../geometry/bounds.js';

/** A bounded corridor is only a proposal; native routing and independent checks decide feasibility. */
export interface Corridor {
  readonly connection: Connection;
  readonly index: number;
}
/** Four endpoint-local sides at two measured distances give exactly eight local alternatives. Pure replay is safe; Layout owns retry and Authoring retains the scene on failure. */
export function localCorridors(plan: RoutePlan, gap: number): readonly Corridor[] {
  const bounds = pointBounds([plan.connection.source, plan.connection.target]);
  return [1, 2].flatMap((scale): readonly Corridor[] =>
    around(plan, bounds, gap * scale, (scale - 1) * 4),
  );
}
/** The final fallback alone may depend on whole-scene bounds; it consumes exactly one attempt. Pure replay is safe; Layout owns retry and Authoring retains the scene on failure. */
export function outsideCorridor(plan: RoutePlan, occupied: readonly Box[], gap: number): Corridor {
  const bounds = union(occupied);
  return corridor(
    plan,
    [
      { x: bounds.x - gap - plan.wire.label.width, y: bounds.y - gap - plan.wire.label.height },
      { x: bounds.x + bounds.width + gap, y: bounds.y - gap - plan.wire.label.height },
    ],
    8,
  );
}
/** Measured label dimensions reserve readable space on either side of the endpoint envelope. */
function around(plan: RoutePlan, bounds: Box, gap: number, offset: number): readonly Corridor[] {
  const left = bounds.x - gap - plan.wire.label.width;
  const right = bounds.x + bounds.width + gap + plan.wire.label.width;
  const top = bounds.y - gap - plan.wire.label.height;
  const bottom = bounds.y + bounds.height + gap + plan.wire.label.height;
  return [
    corridor(
      plan,
      [
        { x: bounds.x, y: top },
        { x: bounds.x + bounds.width, y: top },
      ],
      offset,
    ),
    corridor(
      plan,
      [
        { x: bounds.x, y: bottom },
        { x: bounds.x + bounds.width, y: bottom },
      ],
      offset + 1,
    ),
    corridor(
      plan,
      [
        { x: left, y: bounds.y },
        { x: left, y: bounds.y + bounds.height },
      ],
      offset + 2,
    ),
    corridor(
      plan,
      [
        { x: right, y: bounds.y },
        { x: right, y: bounds.y + bounds.height },
      ],
      offset + 3,
    ),
  ];
}
/** Preserve only the approach checkpoints around each alternative, never an old outside detour. */
function corridor(plan: RoutePlan, middle: readonly Point[], index: number): Corridor {
  return {
    index,
    connection: {
      ...plan.connection,
      checkpoints: [
        ...plan.connection.checkpoints.slice(0, 1),
        ...middle,
        ...plan.connection.checkpoints.slice(-1),
      ],
    },
  };
}
/** Manhattan length, bend count and stable proposal index order only independently valid candidates. Pure replay is safe; Layout owns retry and Authoring retains the scene on failure. */
export function compareRoutes(
  a: { readonly points: readonly Point[]; readonly index: number },
  b: { readonly points: readonly Point[]; readonly index: number },
): number {
  const lengthDifference = routeLength(a.points) - routeLength(b.points);
  if (lengthDifference !== 0) return lengthDifference;
  const bendDifference = bends(a.points) - bends(b.points);
  if (bendDifference !== 0) return bendDifference;
  return a.index - b.index;
}
/** Sum actual segment travel, including any reversal produced by the native engine. */
function routeLength(points: readonly Point[]): number {
  return points.slice(1).reduce((total, point, index): number => {
    const previous = points[index];
    if (previous === undefined) return total;
    return total + Math.abs(point.x - previous.x) + Math.abs(point.y - previous.y);
  }, 0);
}
/** Collinear checkpoints do not count as bends; native paths may retain them for direction constraints. */
function bends(points: readonly Point[]): number {
  return points
    .slice(1, -1)
    .filter((point, index): boolean => turns(points[index], point, points[index + 2])).length;
}
/** Missing neighbours cannot contribute a direction change. */
function turns(a: Point | undefined, b: Point, c: Point | undefined): boolean {
  if (a === undefined || c === undefined) return false;
  return (a.x === b.x) !== (b.x === c.x);
}

/** Public Layout arrange/route/inspect catches structured endpoint faults; Authoring retains the scene and owns correction. */
import type {
  PlacedNode,
  Point,
  ResolvedEndpoint,
  Side,
  Box,
} from '../../contract/records/geometry.js';
import type { VisualWire } from '../../contract/records/input.js';
import { center } from '../geometry/bounds.js';
import { contentBoxes } from './obstacles.js';
import { reject } from '../validation/outcomes.js';
export interface Attachments {
  readonly source: ResolvedEndpoint;
  readonly target: ResolvedEndpoint;
}
/** Resolve the physical visible node; callers never substitute an absent member/object. Layout execute catches faults; Authoring retains the scene and owns correction. */
export function visible(id: string, nodes: readonly PlacedNode[]): PlacedNode {
  const found = nodes.find((node): boolean => node.id === id);
  if (!found) return reject('invalid-input', id, 'Wire attachment node is not visible');
  return found;
}
/** Automatic sides follow centre separation, with a stable horizontal tie break. */
function facing(source: PlacedNode, target: PlacedNode): Side {
  const a = center(source.box);
  const b = center(target.box);
  if (Math.abs(b.x - a.x) >= Math.abs(b.y - a.y)) return horizontalSide(a.x, b.x);
  return verticalSide(a.y, b.y);
}
/** Positive horizontal separation exits on the right; ties use the same stable side. */
function horizontalSide(from: number, to: number): Side {
  if (to >= from) return 'right';
  return 'left';
}
/** Positive vertical separation exits below the source. */
function verticalSide(from: number, to: number): Side {
  if (to >= from) return 'bottom';
  return 'top';
}
/** Named sides are hard intent; row members default to a lateral attachment at the measured row. */
function chooseSide(
  requested: VisualWire['route']['sourceSide'],
  member: string | null,
  source: PlacedNode,
  target: PlacedNode,
): Side {
  if (requested !== 'auto') return requested;
  return automaticSide(member, source, target);
}
/** A table/interface member must connect at its row height, not the centre of the object. */
function automaticSide(member: string | null, source: PlacedNode, target: PlacedNode): Side {
  if (member === null) return facing(source, target);
  return horizontalSide(center(source.box).x, center(target.box).x);
}
/** Orthogonal attachment points lie on the chosen box edge. */
function edge(node: PlacedNode, side: Side): Point {
  const box = node.box;
  const middle = center(box);
  const points = {
    top: { x: middle.x, y: box.y },
    bottom: { x: middle.x, y: box.y + box.height },
    left: { x: box.x, y: middle.y },
    right: { x: box.x + box.width, y: middle.y },
  };
  return points[side];
}
/** Measured member coordinates are node-local and cannot be approximated by row indices. */
function attachment(node: PlacedNode, member: string | null, side: Side): Point {
  if (member === null) return edge(node, side);
  return memberPoint(node, member, side);
}
/** Vertical member-side requests have no row-edge interpretation and are rejected with the member identity. */
function memberPoint(node: PlacedNode, member: string, side: Side): Point {
  if (side === 'top' || side === 'bottom')
    return reject('constraint-conflict', member, 'Member ports require a left or right side', [
      node.id,
      member,
    ]);
  const anchor = node.measured.content.anchors.find((item): boolean => item.member === member);
  if (!anchor)
    return reject('invalid-input', member, 'Measured member anchor is missing', [node.id, member]);
  return { ...edge(node, side), y: node.box.y + anchor.y };
}
/** Resolve both ends before invoking native routing; automatic self-loops leave on different sides. Layout execute catches faults; Authoring retains the scene and owns correction. */
export function endpoints(wire: VisualWire, nodes: readonly PlacedNode[]): Attachments {
  const source = visible(wire.source.node, nodes);
  const target = visible(wire.target.node, nodes);
  const sourceSide = chooseSide(wire.route.sourceSide, wire.source.member, source, target);
  const targetSide = selfTarget(wire, source, target);
  return {
    source: {
      ...wire.source,
      side: sourceSide,
      point: attachment(source, wire.source.member, sourceSide),
    },
    target: {
      ...wire.target,
      side: targetSide,
      point: attachment(target, wire.target.member, targetSide),
    },
  };
}
/** A whole-object self-loop's automatic target uses its bottom; explicit sides remain unchanged. */
function selfTarget(wire: VisualWire, source: PlacedNode, target: PlacedNode): Side {
  if (
    wire.source.node === wire.target.node &&
    wire.route.targetSide === 'auto' &&
    wire.target.member === null
  )
    return 'bottom';
  return chooseSide(wire.route.targetSide, wire.target.member, target, source);
}
/** Exact outward points define marker stubs; the native adapter routes their free corridor without a directed ConnEnd constructor. Layout execute catches faults; Authoring retains the scene and owns correction. */
export function approach(endpoint: ResolvedEndpoint, distance: number): Point {
  const vectors = {
    top: { x: 0, y: -1 },
    right: { x: 1, y: 0 },
    bottom: { x: 0, y: 1 },
    left: { x: -1, y: 0 },
  };
  const vector = vectors[endpoint.side];
  return { x: endpoint.point.x + vector.x * distance, y: endpoint.point.y + vector.y * distance };
}

/** The first fixed obstacle on the outward ray limits optional routing clearance, never marker length. Layout execute catches faults; Authoring retains the scene and owns correction. */
export function departureSpace(endpoint: ResolvedEndpoint, nodes: readonly PlacedNode[]): number {
  const boxes = contentBoxes(nodes.filter((node): boolean => node.id !== endpoint.node));
  return Math.min(Infinity, ...boxes.map((box): number => obstacleDistance(endpoint, box)));
}
/** Normalize every named side to a positive ray; container headers use the same protected content geometry. */
function obstacleDistance(endpoint: ResolvedEndpoint, box: Box): number {
  const point = endpoint.point;
  const rays = {
    right: {
      position: point.x,
      near: box.x,
      far: box.x + box.width,
      across: point.y,
      min: box.y,
      max: box.y + box.height,
    },
    left: {
      position: -point.x,
      near: -box.x - box.width,
      far: -box.x,
      across: point.y,
      min: box.y,
      max: box.y + box.height,
    },
    bottom: {
      position: point.y,
      near: box.y,
      far: box.y + box.height,
      across: point.x,
      min: box.x,
      max: box.x + box.width,
    },
    top: {
      position: -point.y,
      near: -box.y - box.height,
      far: -box.y,
      across: point.x,
      min: box.x,
      max: box.x + box.width,
    },
  };
  return distanceAlongRay(rays[endpoint.side]);
}
/** Obstacles behind the endpoint or outside its attachment axis do not constrain departure. */
function distanceAlongRay(ray: {
  readonly position: number;
  readonly near: number;
  readonly far: number;
  readonly across: number;
  readonly min: number;
  readonly max: number;
}): number {
  if (ray.across <= ray.min || ray.across >= ray.max || ray.far <= ray.position) return Infinity;
  return Math.max(0, ray.near - ray.position);
}

import type { Point } from '../../contract/records/geometry.js';
import { segments } from './paths.js';
import type { Segment } from './paths.js';

interface Ends {
  readonly source: { readonly node: string; readonly member: string | null };
  readonly target: { readonly node: string; readonly member: string | null };
}
/** Endpoint identity is direction independent. Pure replay is safe; Layout owns retries after failed lane selection. */
export function sameEndpoints(a: Ends, b: Ends): boolean {
  return key(a) === key(b);
}
/** Sorting the two endpoint identities makes reciprocal edges members of the same local family. */
function key(wire: Ends): string {
  return JSON.stringify(
    [wire.source, wire.target]
      .map((end): string => JSON.stringify([end.node, end.member]))
      .toSorted(),
  );
}
/** Reject shared interior lanes, allowing only coincident endpoint stubs. Pure replay is safe; Layout owns route retry. */
export function distinctLane(a: readonly Point[], b: readonly Point[]): boolean {
  const stubs = sharedStubs(a, b);
  return segments(a).every((left): boolean =>
    segments(b).every((right): boolean => clearPair(left, right, stubs)),
  );
}
/** Shared endpoint rays permit only the longer of the two explicit endpoint stubs. */
function sharedStubs(a: readonly Point[], b: readonly Point[]): readonly Segment[] {
  return endpointSegments(a).flatMap((left): readonly Segment[] =>
    endpointSegments(b)
      .filter((right): boolean => left.a.x === right.a.x && left.a.y === right.a.y)
      .flatMap((right): readonly Segment[] => [left, right]),
  );
}
/** Native approach vertices bound the exception; a complete direct path cannot exempt itself. */
function endpointSegments(points: readonly Point[]): readonly Segment[] {
  if (points.length < 3) return [];
  return [points, points.toReversed()].flatMap((ends): readonly Segment[] => firstSegment(ends));
}
/** Missing endpoint vertices cannot grant shared travel. */
function firstSegment(points: readonly Point[]): readonly Segment[] {
  const a = points[0];
  const b = points[1];
  if (a === undefined || b === undefined) return [];
  return [{ a, b }];
}
/** Positive shared travel is legal only when completely contained in a shared endpoint stub. */
function clearPair(a: Segment, b: Segment, stubs: readonly Segment[]): boolean {
  if (!collinearOverlap(a, b)) return true;
  const shared = {
    a: {
      x: Math.max(Math.min(a.a.x, a.b.x), Math.min(b.a.x, b.b.x)),
      y: Math.max(Math.min(a.a.y, a.b.y), Math.min(b.a.y, b.b.y)),
    },
    b: {
      x: Math.min(Math.max(a.a.x, a.b.x), Math.max(b.a.x, b.b.x)),
      y: Math.min(Math.max(a.a.y, a.b.y), Math.max(b.a.y, b.b.y)),
    },
  };
  return stubs.some((stub): boolean => contains(stub, shared.a) && contains(stub, shared.b));
}
/** Inclusive bounds preserve shared stub borders without permitting an interior lane. */
function contains(segment: Segment, point: Point): boolean {
  return (
    point.x >= Math.min(segment.a.x, segment.b.x) &&
    point.x <= Math.max(segment.a.x, segment.b.x) &&
    point.y >= Math.min(segment.a.y, segment.b.y) &&
    point.y <= Math.max(segment.a.y, segment.b.y)
  );
}
/** Orthogonal interval intersection counts travel shared in either direction, excluding point crossings. */
function collinearOverlap(a: Segment, b: Segment): boolean {
  if (horizontal(a) && horizontal(b)) return horizontalOverlap(a, b);
  return verticalOverlap(a, b);
}
/** Vertical segments need the same x coordinate and positive shared y extent. */
function verticalOverlap(a: Segment, b: Segment): boolean {
  return (
    a.a.x === a.b.x && b.a.x === b.b.x && a.a.x === b.a.x && overlap(a.a.y, a.b.y, b.a.y, b.b.y)
  );
}
/** Boundary tangencies and crossings have zero shared travel. */
function overlap(a: number, b: number, c: number, d: number): boolean {
  return Math.min(Math.max(a, b), Math.max(c, d)) > Math.max(Math.min(a, b), Math.min(c, d));
}

/** Horizontal classification is independent of travel direction. */
function horizontal(segment: Segment): boolean {
  return segment.a.y === segment.b.y;
}

/** Parallel horizontal intervals share travel only on the same row. */
function horizontalOverlap(a: Segment, b: Segment): boolean {
  return a.a.y === b.a.y && overlap(a.a.x, a.b.x, b.a.x, b.b.x);
}

import type { VisualWire } from '../../contract/records/input.js';
import type { PlacedNode, Point, Box } from '../../contract/records/geometry.js';
import { point } from '../../contract/records/geometry.js';
import type { Connection, RouteValue, Obstacle } from '../../contract/records/problem.js';
import type { SupplementalMeasurements } from '../../contract/types.js';
import type { RoutingContext } from '../../contract/types.js';
import type { Result } from '../../contract/errors.js';
import type { Attachments } from './endpoints.js';
import { approach, endpoints, visible, departureSpace } from './endpoints.js';
import { validRoute } from './checks.js';
import { union } from '../geometry/bounds.js';
import { samePoint } from '../geometry/intersections.js';
import { reject, requireValue } from '../validation/outcomes.js';
export interface RoutePlan {
  readonly wire: VisualWire;
  readonly attachments: Attachments;
  readonly connection: Connection;
  readonly manual: readonly Point[] | null;
  readonly clearance: number;
}
/** Plan exact attachments and distinct local approaches. Public Layout execute catches faults; Authoring retains the scene and owns correction. */
export function plan(
  wire: VisualWire,
  nodes: readonly PlacedNode[],
  metrics: SupplementalMeasurements,
  context: RoutingContext,
  parallel: number,
): RoutePlan {
  const resolved = endpoints(wire, nodes);
  const clearance = context.options.routeClearance * 2;
  const departure = clearance * (parallel + 1);
  const sourceSpace = departureSpace(resolved.source, nodes);
  const targetSpace = departureSpace(resolved.target, nodes);
  const sourceDistance = departureDistance(
    wire.id,
    metrics.markers[wire.sourceMarker].advance,
    departure,
    sourceSpace,
  );
  const targetDistance = departureDistance(
    wire.id,
    metrics.markers[wire.targetMarker].advance,
    departure,
    targetSpace,
  );
  const source = approach(resolved.source, sourceDistance);
  const target = approach(resolved.target, targetDistance);
  return {
    wire,
    attachments: resolved,
    manual: wire.route.manual ?? null,
    clearance: Math.min(
      context.options.routeClearance,
      sourceSpace - sourceDistance,
      targetSpace - targetDistance,
    ),
    connection: {
      id: wire.id,
      source: resolved.source.point,
      target: resolved.target.point,
      sourceSide: resolved.source.side,
      targetSide: resolved.target.side,
      sourceApproach: source,
      targetApproach: target,
      checkpoints: parallelCheckpoints(
        source,
        target,
        resolved.source.side,
        [visible(wire.source.node, nodes), visible(wire.target.node, nodes)],
        parallel,
        clearance,
        wire.label.height,
      ),
    },
  };
}
/** Reserve at most a third of the free ray for optional approach so opposite native endpoints remain distinct; required marker advance is never reduced. */
function departureDistance(id: string, advance: number, preferred: number, space: number): number {
  if (advance > space)
    return reject(
      'constraint-conflict',
      id,
      'Required endpoint marker approach is blocked by fixed content',
      [id],
    );
  return Math.max(advance, Math.min(preferred + advance, space / 3));
}
/** Parallel wires reserve distinct outside lanes while keeping the same exact semantic endpoints. */
function parallelCheckpoints(
  source: Point,
  target: Point,
  side: Connection['sourceSide'],
  nodes: readonly PlacedNode[],
  parallel: number,
  gap: number,
  labelHeight: number,
): readonly Point[] {
  if (parallel === 0) return [source, target];
  const bounds = union(nodes.map((node): Box => node.box));
  const distance = (parallel + 1) * (gap + labelHeight);
  return laneCheckpoints(source, target, side, bounds.x - distance, bounds.y - distance);
}
/** Outside checkpoint pairs create a visible lane along the endpoint's perpendicular axis. */
function laneCheckpoints(
  source: Point,
  target: Point,
  side: Connection['sourceSide'],
  x: number,
  y: number,
): readonly Point[] {
  if (side === 'left' || side === 'right')
    return [source, { x: source.x, y }, { x: target.x, y }, target];
  return [source, { x, y: source.y }, { x, y: target.y }, target];
}
/** Retain valid authored points. Public Layout execute catches lock faults; Authoring retains the scene and owns correction. */
export function manual(
  plan: RoutePlan,
  obstacles: readonly Obstacle[],
  metrics: SupplementalMeasurements,
): RouteValue | null {
  if (plan.manual === null) return null;
  const valid = validRoute(
    plan.manual,
    plan.attachments.source,
    plan.attachments.target,
    obstacles.map((item): Box => item.box),
    plan.wire,
    metrics,
  );
  if (valid) return { id: plan.wire.id, points: plan.manual };
  return invalidManual(plan);
}
/** Soft invalid geometry requests native rerouting; a hard lock instead produces a named conflict. */
function invalidManual(plan: RoutePlan): RouteValue | null {
  if (plan.wire.route.locked)
    return reject(
      'constraint-conflict',
      plan.wire.id,
      'Locked manual route no longer matches ports or clear content',
      [plan.wire.id],
    );
  return null;
}
/** Remove only consecutive duplicate points from native output; authored manual vertices are untouched. */
function checkedRoute(value: RouteValue): RouteValue {
  value.points.forEach(checkPoint);
  return {
    ...value,
    points: value.points.filter((item, index): boolean => distinct(item, value.points[index - 1])),
  };
}
/** A missing predecessor identifies the first native point. */
function distinct(point: Point, previous: Point | undefined): boolean {
  if (previous === undefined) return true;
  return !samePoint(point, previous);
}
/** Native nonfinite/oversized coordinates cannot reach path generation. */
function checkPoint(value: Point): void {
  if (!point.safeParse(value).success)
    reject('engine-failed', 'routing', 'Native route contains invalid coordinates');
}
/** Owned search outcome; only geometric infeasibility is retryable inside the candidate budget. */
export type NativeRouteOutcome =
  | { readonly kind: 'candidate-infeasible' }
  | { readonly kind: 'routed'; readonly routes: readonly RouteValue[] };
/** Native failures remain typed until the protected Layout boundary; cancellation wins even after an infeasible result. Public Layout execute catches faults; Authoring retains the scene and owns correction. */
export async function routeNative(
  connections: readonly Connection[],
  obstacles: readonly Obstacle[],
  context: RoutingContext,
): Promise<NativeRouteOutcome> {
  requireValue(await context.dependencies.jobs.checkpoint(context.job));
  const result = await context.dependencies.routing.route({
    connections,
    obstacles,
    clearance: context.options.routeClearance,
  });
  requireValue(await context.dependencies.jobs.checkpoint(context.job));
  return checkedOutcome(connections, result);
}
/** Skip only the owned geometric failure; requireValue preserves operational diagnostics for public execute. */
function checkedOutcome(
  connections: readonly Connection[],
  result: Result<readonly RouteValue[]>,
): NativeRouteOutcome {
  if (!result.ok && result.error.code === 'candidate-infeasible')
    return { kind: 'candidate-infeasible' };
  return { kind: 'routed', routes: checkedValues(connections, requireValue(result)) };
}
/** Exact identities and finite coordinates are operational requirements, never a reason to silently try another candidate. */
function checkedValues(
  connections: readonly Connection[],
  values: readonly RouteValue[],
): readonly RouteValue[] {
  const expected = connections.map((item): string => item.id).toSorted();
  const actual = values.map((item): string => item.id).toSorted();
  if (JSON.stringify(expected) !== JSON.stringify(actual))
    reject('engine-failed', 'routing', 'Native route set differs from requested connections');
  return values.map(checkedRoute);
}

import type { VisualSection } from '../../contract/records/input.js';
import type { PlacedNode, RoutedWire, Box, Point } from '../../contract/records/geometry.js';
import type { RouteValue, Obstacle } from '../../contract/records/problem.js';
import type { SupplementalMeasurements } from '../../contract/types.js';
import type { RoutingContext } from '../../contract/types.js';
import type { RoutePlan } from './native.js';
import { plan, manual, routeNative } from './native.js';
import { obstacles, contentBoxes } from './obstacles.js';
import { distinctLane, sameEndpoints } from './lanes.js';
import { markerBox, validRoute } from './checks.js';
import { labelBox } from './labels.js';
import { curvePath, linePath, segments } from './paths.js';
import { accumulate } from '../arrangement/sequential.js';
import { localCorridors, outsideCorridor, compareRoutes } from './corridors.js';
import type { Corridor } from './corridors.js';
import { reject } from '../validation/outcomes.js';
interface WireContext {
  readonly placement: RoutingContext;
  readonly metrics: SupplementalMeasurements;
  readonly obstacles: readonly Obstacle[];
  readonly prior: readonly RoutedWire[];
}
/** Ranking metadata stays private and must never enter the strict public scene record. */
interface RankedRoute {
  readonly wire: RoutedWire;
  readonly points: readonly Point[];
  readonly index: number;
}
/** Marker and accepted label regions are reserved for subsequent labels. */
function reserved(plans: readonly RoutePlan[], context: WireContext): readonly Box[] {
  return plans.flatMap((item): readonly Box[] => [
    markerBox(item.attachments.source, context.metrics.markers[item.wire.sourceMarker]),
    markerBox(item.attachments.target, context.metrics.markers[item.wire.targetMarker]),
    ...routeBoxes([
      item.connection.source,
      item.connection.sourceApproach ?? item.connection.source,
    ]),
    ...routeBoxes([
      item.connection.target,
      item.connection.targetApproach ?? item.connection.target,
    ]),
  ]);
}
/** Wire rendering retains authoritative label/marker/style data and derives only path geometry. */
function wire(
  plan: RoutePlan,
  points: readonly Point[],
  labelBox: Box,
  context: WireContext,
): RoutedWire {
  const obstacles = context.obstacles.map((item): Box => item.box);
  const path =
    plan.wire.route.route === 'curve'
      ? curvePath(points, context.placement.options.routeClearance / 2, obstacles)
      : linePath(points);
  return {
    id: plan.wire.id,
    ...plan.attachments,
    points,
    path,
    labelBox,
    measuredLabel: plan.wire.label,
    sourceMarker: plan.wire.sourceMarker,
    targetMarker: plan.wire.targetMarker,
    style: plan.wire.style,
  };
}
/** Candidate validation is independent of native success and reserves the candidate's own wire path. */
function candidate(
  plan: RoutePlan,
  points: readonly Point[],
  occupied: readonly Box[],
  context: WireContext,
  retained = false,
): RoutedWire | null {
  if (
    !validRoute(
      points,
      plan.attachments.source,
      plan.attachments.target,
      context.obstacles.map((item): Box => item.box),
      plan.wire,
      context.metrics,
    )
  )
    return null;
  if (!laneAvailable(plan, points, context, retained)) return null;
  const label = labelBox(
    points,
    plan.wire.label,
    [...occupied, ...routeBoxes(points)],
    context.placement.options.labelGap,
  );
  return labelledCandidate(plan, points, label, context);
}
/** Candidate infeasibility consumes one attempt; operational and cancellation failures propagate immediately. */
async function attempt(
  plan: RoutePlan,
  corridor: Corridor,
  occupied: readonly Box[],
  context: WireContext,
): Promise<RoutedWire | null> {
  const placement = {
    ...context.placement,
    options: { ...context.placement.options, routeClearance: candidateClearance(plan, context) },
  };
  const values = await routeNative([corridor.connection], context.obstacles, placement);
  if (values.kind === 'candidate-infeasible') return null;
  const value = values.routes[0];
  if (value === undefined) return reject('engine-failed', plan.wire.id, 'Routing omitted a wire');
  return candidate(plan, value.points, occupied, context);
}
/** Eight local alternatives are inspected and ranked before the one permitted outside attempt. */
async function alternatives(
  plan: RoutePlan,
  occupied: readonly Box[],
  context: WireContext,
): Promise<RoutedWire> {
  const gap = context.placement.options.routeClearance * 2 + context.placement.options.labelGap;
  const candidates = await accumulate<Corridor, readonly RankedRoute[]>(
    localCorridors(plan, gap),
    [],
    async (accepted, corridor): Promise<readonly RankedRoute[]> => {
      const next = await attempt(plan, corridor, occupied, context);
      if (next === null) return accepted;
      return [...accepted, { wire: next, points: next.points, index: corridor.index }];
    },
  );
  const best = candidates.toSorted(compareRoutes)[0];
  if (best !== undefined) return best.wire;
  const outside = await attempt(plan, outsideCorridor(plan, occupied, gap), occupied, context);
  if (outside !== null) return outside;
  return reject(
    'constraint-conflict',
    plan.wire.id,
    'No valid labelled route within the initial, eight local and one outside candidate budget',
    [plan.wire.id],
  );
}
/** Valid manual geometry is retained exactly; label infeasibility never silently discards authored points. */
async function labelled(
  plan: RoutePlan,
  saved: RouteValue | null,
  occupied: readonly Box[],
  context: WireContext,
): Promise<RoutedWire> {
  if (saved !== null) return savedWire(plan, saved, occupied, context);
  const initial = await attempt(
    plan,
    { connection: plan.connection, index: -1 },
    occupied,
    context,
  );
  if (initial !== null) return initial;
  return alternatives(plan, occupied, context);
}
/** An authored route with no clear label or a collision with a prior label has a named correction path. */
function savedWire(
  plan: RoutePlan,
  saved: RouteValue,
  occupied: readonly Box[],
  context: WireContext,
): RoutedWire {
  const result = candidate(plan, saved.points, occupied, context, true);
  if (result !== null) return result;
  return reject(
    'constraint-conflict',
    plan.wire.id,
    'Manual route has no clear space for its measured label or crosses a reserved label',
    [plan.wire.id],
  );
}
/** Accepted labels constrain later routes; every retained manual path constrains label placement from the start. */
async function labelAll(
  plans: readonly RoutePlan[],
  saved: readonly RouteValue[],
  occupied: readonly Box[],
  context: WireContext,
): Promise<readonly RoutedWire[]> {
  return accumulate<RoutePlan, readonly RoutedWire[]>(
    plans,
    [],
    async (result, plan): Promise<readonly RoutedWire[]> => {
      const current = withPriorLabels(context, result);
      const occupiedSpace = [
        ...occupied,
        ...result.map((item): Box => item.labelBox),
        ...result.flatMap((item): readonly Box[] => routeBoxes(item.points)),
        ...saved.flatMap((item): readonly Box[] => routeBoxes(item.points)),
      ];
      const next = await labelled(
        plan,
        saved.find((item): boolean => item.id === plan.wire.id) ?? null,
        occupiedSpace,
        current,
      );
      return [...result, next];
    },
  );
}
/** Accepted labels become real routing obstacles for subsequent connections. */
function withPriorLabels(context: WireContext, wires: readonly RoutedWire[]): WireContext {
  const labels = wires.map((wire): Obstacle => ({ id: `label:${wire.id}`, box: wire.labelBox }));
  return { ...context, prior: wires, obstacles: [...context.obstacles, ...labels] };
}
/** Exact segment footprints let labelGap protect both sides equally; a positive one-sided box biases labels away from right/bottom. */
function routeBoxes(points: readonly Point[]): readonly Box[] {
  return segments(points).map((segment): Box => ({
    x: Math.min(segment.a.x, segment.b.x),
    y: Math.min(segment.a.y, segment.b.y),
    width: Math.abs(segment.a.x - segment.b.x),
    height: Math.abs(segment.a.y - segment.b.y),
  }));
}
/** Final rounded paths account for all label rectangles, including ones added later in source order. */
function finalPaths(
  wires: readonly RoutedWire[],
  section: VisualSection,
  context: WireContext,
): readonly RoutedWire[] {
  const occupied = [
    ...context.obstacles.map((item): Box => item.box),
    ...wires.map((item): Box => item.labelBox),
  ];
  return wires.map((wire): RoutedWire =>
    finalPath(wire, section, occupied, context.placement.options.routeClearance / 2),
  );
}
/** Orthogonal routes retain their exact polyline; curves round only corners with free labelled space. */
function finalPath(
  wire: RoutedWire,
  section: VisualSection,
  occupied: readonly Box[],
  radius: number,
): RoutedWire {
  const source = section.wires.find((item): boolean => item.id === wire.id);
  if (source?.route.route !== 'curve') return wire;
  return { ...wire, path: curvePath(wire.points, radius, occupied) };
}
/** Reciprocal and parallel edges share one endpoint-local ordinal, stable in source order. */
function parallel(section: VisualSection, index: number): number {
  const current = section.wires[index];
  if (current === undefined) return 0;
  return section.wires.slice(0, index).filter((item): boolean => sameEndpoints(current, item))
    .length;
}
/** Route fixed nodes and retain manual geometry. Public Layout arrange/route execute catches structured faults; Authoring retains the scene and draft on failure. */
export async function routeWires(
  section: VisualSection,
  nodes: readonly PlacedNode[],
  metrics: SupplementalMeasurements,
  placement: RoutingContext,
): Promise<readonly RoutedWire[]> {
  const context: WireContext = { metrics, placement, obstacles: obstacles(nodes), prior: [] };
  const plans = section.wires.map((item, index): RoutePlan =>
    plan(item, nodes, metrics, placement, parallel(section, index)),
  );
  const saved = plans.flatMap(
    (item): RouteValue | readonly RouteValue[] => manual(item, context.obstacles, metrics) ?? [],
  );
  const labelled = await labelAll(
    plans,
    saved,
    [...contentBoxes(nodes), ...reserved(plans, context)],
    context,
  );
  return finalPaths(labelled, section, context);
}

/** Retained manual geometry takes precedence; automatic peers must use distinct endpoint-local lanes. */
function laneAvailable(
  plan: RoutePlan,
  points: readonly Point[],
  context: WireContext,
  retained: boolean,
): boolean {
  if (retained) return true;
  const peers = context.prior.filter((item): boolean => sameEndpoints(plan.attachments, item));
  return peers.every((item): boolean => distinctLane(points, item.points));
}

/** A missing adjacent label invalidates the proposal without hiding a partial wire. */
function labelledCandidate(
  plan: RoutePlan,
  points: readonly Point[],
  label: Box | null,
  context: WireContext,
): RoutedWire | null {
  if (label === null) return null;
  return wire(plan, points, label, context);
}

/** Prior labels must not swallow native approach points when optional obstacle buffers are expanded. */
function candidateClearance(plan: RoutePlan, context: WireContext): number {
  const points = [
    plan.connection.sourceApproach ?? plan.connection.source,
    plan.connection.targetApproach ?? plan.connection.target,
  ];
  const distances = points.flatMap((point): readonly number[] =>
    context.obstacles.map((obstacle): number => boxDistance(point, obstacle.box) / 2),
  );
  return Math.min(plan.clearance, ...distances);
}
/** Distance to a rectangle bounds optional native inflation without changing required marker dimensions. */
function boxDistance(point: Point, box: Box): number {
  return Math.max(
    0,
    box.x - point.x,
    point.x - box.x - box.width,
    box.y - point.y,
    point.y - box.y - box.height,
  );
}

/** Public Layout boundary scenarios are replayable; Vitest owns assertion reporting and the developer fixes failures before rerunning. */
