        }),
      ).valid,
    ).toBe(false);
    const moved = {
      ...scene,
      sections: [
        {
          ...sourceSection,
          nodes: sourceSection.nodes.map((node) => ({ ...node, box: { ...node.box, x: 0, y: 0 } })),
        },
      ],
    };
    expect(
      value(
        layout.inspect({
          projection: source,
          measurements: input.measurements,
          options: settings,
          candidate: moved,
        }),
      ).valid,
    ).toBe(false);
    const farLabel = {
      ...scene,
      sections: [
        {
          ...sourceSection,
          wires: sourceSection.wires.map((wire) => ({
            ...wire,
            labelBox: { ...wire.labelBox, x: -10000 },
          })),
        },
      ],
    };
    expect(
      value(
        layout.inspect({
